ps://www.parkrun.ie/wexfordracecourse/", "source_url": "https://www.parkrun.ie/wexfordracecourse/"}, "after": {"county": "Wexford", "region": "Leinster"}, "evidenceIds": ["ie-provinces"], "method": "Province from existing exact county label; existing county evidence not reverified"}, {"slug": "wicklow-half-marathon-10k-2027", "before": {"country": "Ireland", "city": "Wicklow", "county": "County Wicklow", "region": null, "area": "Wicklow town and coast", "website": "https://eventmaster.ie/event/52ADsQvsEz", "source_url": "https://eventmaster.ie/event/52ADsQvsEz"}, "after": {"county": "County Wicklow", "region": "Leinster"}, "evidenceIds": ["ie-provinces"], "method": "Province from existing exact county label; existing county evidence not reverified"}, {"slug": "wild-atlantic-ultra", "before": {"country": "Ireland", "city": "Louisburgh", "county": "Mayo", "region": null, "area": "Louisburgh", "website": "https://www.wau50.com/", "source_url": "https://www.wau50.com/"}, "after": {"county": "Mayo", "region": "Connacht"}, "evidenceIds": ["ie-provinces"], "method": "Province from existing exact county label; existing county evidence not reverified"}, {"slug": "world-half-marathon-festival", "before": {"country": "Ireland", "city": "Donadea", "county": "Kildare", "region": null, "area": "Donadea", "website": "https://eventmaster.ie/event/vZ4qcPoSb4/5gZNcbzs6", "source_url": "https://eventmaster.ie/event/vZ4qcPoSb4/5gZNcbzs6"}, "after": {"county": "Kildare", "region": "Leinster"}, "evidenceIds": ["ie-provinces"], "method": "Province from existing exact county label; existing county evidence not reverified"}]$county_regions$::jsonb)
 AS c(slug text, before jsonb, after jsonb, "evidenceIds" jsonb, method text)
), eligible AS MATERIALIZED (
 SELECT e.*,c.after,c."evidenceIds",c.method FROM events e JOIN corrections c ON e.slug=c.slug
 WHERE e.country IS NOT DISTINCT FROM c.before->>'country'
 AND e.city IS NOT DISTINCT FROM c.before->>'city'
 AND e.county IS NOT DISTINCT FROM c.before->>'county'
 AND e.region IS NOT DISTINCT FROM c.before->>'region'
 AND e.area IS NOT DISTINCT FROM c.before->>'area'
 AND e.website IS NOT DISTINCT FROM c.before->>'website'
 AND e.source_url IS NOT DISTINCT FROM c.before->>'source_url'
 AND NOT EXISTS (SELECT 1 FROM app_meta m WHERE m.key='fixture-geography:2026-10-26:county-region:'||e.slug)
 FOR UPDATE OF e
), backups AS (
 INSERT INTO app_meta(key,value)
 SELECT 'fixture-geography:2026-10-26:county-region:'||slug,
 jsonb_build_object('before',to_jsonb(eligible)-'after'-'evidenceIds'-'method','after',after,'evidenceIds',"evidenceIds",'method',method,'checkedAt','2026-10-26')::text
 FROM eligible ON CONFLICT(key) DO NOTHING RETURNING key
)
UPDATE events e SET county=x.after->>'county',region=x.after->>'region',updated_at=now()
FROM eligible x JOIN backups b ON b.key='fixture-geography:2026-10-26:county-region:'||x.slug WHERE e.id=x.id;
